const config = $('Pipeline Config').first().json;
function cleanJsonText(raw) {
  let text = raw;

  if (typeof raw === 'object' && raw !== null) {
    if (raw.parts?.[0]?.text) text = raw.parts[0].text;
    else if (raw.output?.[0]?.content?.[0]?.text) text = raw.output[0].content[0].text;
    else text = JSON.stringify(raw);
  }

  return String(text || '')
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();
}

function safeParse(raw) {
  try {
    return JSON.parse(cleanJsonText(raw));
  } catch (e) {
    return null;
  }
}

function compactDialogue(segments, maxLines = 10) {
  if (!Array.isArray(segments)) return [];
  return segments
    .flatMap(segment => (segment.dialogue || []).map(d => ({
      timecode: segment.timecode ?? null,
      speaker: d.speaker ?? null,
      line: d.line ?? null
    })))
    .filter(d => d.line)
    .slice(0, maxLines);
}

function firstHost(original) {
  return Array.isArray(original?.people) ? original.people[0] : null;
}

function uniqueLocations(segments) {
  if (!Array.isArray(segments)) return [];
  return [...new Set(segments.map(s => s.location).filter(Boolean))].slice(0, 3);
}

function buildCanonicalVisualAnchor(original, host) {
  const locations = uniqueLocations(original?.segments);
  const rawVisual = original?.hook?.visual ?? null;
  const hostParts = [
    host?.role ? 'role: ' + host.role : null,
    host?.appearance ? 'appearance: ' + host.appearance : null,
    host?.outfit ? 'outfit: ' + host.outfit : null,
    host?.key_action ? 'action: ' + host.key_action : null
  ].filter(Boolean);

  const settingParts = [
    locations.length ? 'place/location: ' + locations.join(', ') : null,
    rawVisual ? 'hook visual: ' + rawVisual : null
  ].filter(Boolean);

  return {
    raw_visual: rawVisual,
    speaker_identity: hostParts.join('; ') || rawVisual || null,
    place: locations[0] ?? null,
    interior_background: locations.join(', ') || rawVisual || null,
    setting: settingParts.join('; ') || null,
    camera: original?.style?.camera ?? null,
    lighting: original?.style?.lighting ?? null,
    pacing: original?.style?.pacing ?? null,
    transitions: original?.style?.transitions ?? null,
    must_copy: [
      rawVisual ? 'raw visual: ' + rawVisual : null,
      locations.length ? 'place/interior/background: ' + locations.join(', ') : null,
      original?.style?.camera ? 'camera: ' + original.style.camera : null,
      host?.appearance ? 'speaker appearance: ' + host.appearance : null,
      host?.outfit ? 'outfit: ' + host.outfit : null
    ].filter(Boolean)
  };
}

return items.map(item => {
  const original = safeParse(item.json['Original json file']);
  const dna = safeParse(item.json.DNA_Extractor);
  const host = firstHost(original);
  const canonicalVisualAnchor = buildCanonicalVisualAnchor(original, host);

  const compactOriginal = {
    project: original?.project ?? null,
    format: original?.format ?? null,
    structure: original?.structure ?? null,
    core_idea: original?.core_idea ?? null,
    channel: original?.channel ?? null,
    hook: original?.hook ?? null,
    style: original?.style ?? null,
    people: Array.isArray(original?.people) ? original.people.slice(0, 3) : [],
    dialogue_sample: compactDialogue(original?.segments, 10),
    segment_summaries: Array.isArray(original?.segments)
      ? original.segments.slice(0, 6).map(segment => ({
          timecode: segment.timecode ?? null,
          location: segment.location ?? null,
          action: segment.action ?? null,
          purpose: segment.purpose ?? null,
          dialogue_lines: (segment.dialogue || []).map(d => d.line).filter(Boolean).slice(0, 2),
          captions: (segment.captions || []).map(c => c.text).filter(Boolean).slice(0, 2)
        }))
      : [],
    overlays: Array.isArray(original?.overlays) ? original.overlays.slice(0, 8) : [],
    format_dna: original?.format_dna ?? null
  };

  item.json.adapter_input = {
    source_fidelity: {
      rule: 'Preserve the original source format and concrete visual anchor unless it conflicts with the product adaptation or AI feasibility.',
      must_preserve_when_present: [
        'speaker count and role',
        'speaker gender/age range as observed',
        'main location/background',
        'selfie/talking-head/street-interview camera style',
        'pacing and cut pattern',
        'original topic if it already overlaps with the configured product, its audiences, value propositions, and adjacent user problems'
      ],
      do_not_generalize: [
        'Do not replace a car selfie with a generic bedroom, classroom, or studio.',
        'Do not change a male host into a female host or a student unless the source says that.',
        'Do not remove a topic relevant to the configured product if the source already contains it.'
      ]
    },
    original_video: compactOriginal,
    visual_anchor: {
      canonical: canonicalVisualAnchor,
      source_hook_visual: original?.hook?.visual ?? null,
      source_setting: uniqueLocations(original?.segments),
      source_camera: original?.style?.camera ?? null,
      source_lighting: original?.style?.lighting ?? null,
      source_pacing: original?.style?.pacing ?? null,
      source_transitions: original?.style?.transitions ?? null,
      source_host: host ? {
        role: host.role ?? null,
        appearance: host.appearance ?? null,
        outfit: host.outfit ?? null,
        key_action: host.key_action ?? null
      } : null
    },
    creative_dna: dna,
    product: {
      ...config.product,
      brand_mention_policy: 'avoid spoken brand mentions; final branded outro will be added separately',
      text_rendering_policy: 'video models should not render readable text; captions/subtitles/brand cards will be added in post'
    }
  };

  return item;
});

return [{
  json: {
    product: {
      name: "Speechify",
      description: "An app that turns books, PDFs, articles, emails, and documents into audio using AI voices.",
      audiences: ["people with ADHD or focus challenges", "students", "professionals", "busy readers"],
      value_props: ["save time", "listen instead of read", "consume more content", "learn while multitasking"],
      target_markets: ["US", "CA", "GB", "AU"]
    },
    scoring: {
      allowed_languages: ["en"],
      max_source_duration_sec: 60,
      target_video_duration_sec: 15,
      min_product_fit_score: 0.60,
      min_ai_video_generation_score: 0.60,
      reject_local_or_cultural_concepts: true
    },
    generation: {
      aspect_ratio: "9:16",
      seedance_model: "bytedance/seedance-2",
      kling_model: "kling-3.0/video"
    }
  }
}];
